-- Read-only schema fingerprint (13 dimensions). Run on the target after reconciliation and
-- compare with expected_fingerprint_after_part2 in docs/migration-reconciliation-manifest.json.
-- Safe: SELECT only. Usage: Supabase SQL editor, or psql -At -f this file.
select 'fn' k, count(*) n, md5(string_agg(x, ',' order by x)) h from (select n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||'):'||md5(p.prosrc)||':'||p.prosecdef||':'||coalesce(array_to_string(p.proconfig,','),'') x from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname <> 'rls_auto_enable') s
union all select 'fnacl', count(*), md5(string_agg(x, ',' order by x)) from (select n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||'):'||array_to_string(array(select a from unnest(coalesce(p.proacl, '{}'::aclitem[])) a where a::text ~ '^(anon|authenticated|service_role)?='), ',') x from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname <> 'rls_auto_enable') s
union all select 'pol', count(*), md5(string_agg(x, ',' order by x)) from (select schemaname||'.'||tablename||'.'||policyname||':'||cmd||':'||coalesce(qual,'')||':'||coalesce(with_check,'')||':'||array_to_string(roles,';') x from pg_policies where schemaname in ('public','storage') and policyname not like 'supabase%') s
union all select 'con', count(*), md5(string_agg(x, ',' order by x)) from (select r.relname||':'||co.conname||':'||pg_get_constraintdef(co.oid) x from pg_constraint co join pg_class r on r.oid=co.conrelid join pg_namespace n on n.oid=r.relnamespace where n.nspname in ('public','private')) s
union all select 'trg', count(*), md5(string_agg(x, ',' order by x)) from (select c.relname||':'||t.tgname||':'||pg_get_triggerdef(t.oid) x from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','private')) s
union all select 'col', count(*), md5(string_agg(x, ',' order by x)) from (select table_schema||'.'||table_name||'.'||column_name||':'||udt_name||':'||coalesce(column_default,'')||':'||is_nullable x from information_schema.columns where table_schema in ('public','private')) s
union all select 'idx', count(*), md5(string_agg(indexdef, ',' order by indexdef)) from pg_indexes where schemaname in ('public','private')
union all select 'grant', count(*), md5(string_agg(x, ',' order by x)) from (select grantee||':'||table_schema||'.'||table_name||':'||privilege_type x from information_schema.role_table_grants where table_schema in ('public','private') and grantee in ('anon','authenticated','service_role')) s
union all select 'colgrant', count(*), md5(string_agg(x, ',' order by x)) from (select grantee||':'||table_name||'.'||column_name||':'||privilege_type x from information_schema.column_privileges where table_schema='public' and grantee in ('anon','authenticated')) s
union all select 'rls', count(*), md5(string_agg(x, ',' order by x)) from (select n.nspname||'.'||c.relname||':'||c.relrowsecurity x from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r') s
union all select 'bucket', count(*), md5(string_agg(x, ',' order by x)) from (select id||':'||public::text||':'||coalesce(file_size_limit::text,'')||':'||coalesce(array_to_string(allowed_mime_types,';'),'') x from storage.buckets) s
union all select 'catalog', count(*), md5(string_agg(x, ',' order by x)) from (select key||'|'||category||'|'||sort_order||'|'||description x from public.permissions) s
union all select 'roleperm', count(*), md5(string_agg(x, ',' order by x)) from (select role||':'||permission_key x from public.role_permissions) s
order by 1;
